pragma solidity >=0.8.0;

contract ArrayEventProbe {
    uint256[] public vals;

    event Arr(uint256[] vals);
    event Tup(uint256 a, string b, bytes c);

    function push(uint256 v) public returns (uint256) {
        vals.push(v);
        return vals.length;
    }

    function emitArr() public {
        emit Arr(vals);
    }

    function emitTup(string memory sv, bytes memory d) public {
        emit Tup(42, sv, d);
    }
}
